@startuml
class Factory {
  +id : int
}

class Machine {
  +serialNumber : string
  +make : string
  +model : string
  +purchaseDate : date
}

class Worker {
  +id : int
  +firstName : string
  +lastName : string
  +birthDate : date
  +address : string
  +skills : string[]
}

class ProductType {
  +id : int
  +name : string
  +material : string
  +weight : float
}

class Product {
  +id : int
}

class Client {
  +id : int
  +name : string
  +address : string
  +phoneNumber : string
  +contactPerson : string
}

class PurchaseOrder {
  +orderNumber : string
  +orderDate : date
  +expectedDeliveryDate : date
  +actualDeliveryDate : date
}

class OrderLine {
  +quantity : int
}

Factory "1" *-- "*" Machine
Machine "*" -- "*" Worker
Machine "1" -- "*" ProductType
ProductType "1" -- "*" Product
Client "1" -- "*" PurchaseOrder
PurchaseOrder "1" *-- "1..*" OrderLine
OrderLine "*" -- "1" Product
@enduml

